{"sentences": [{"sentence_id": "s1", "sentence": "Four trials test clemastine in multiple sclerosis, including one Phase 3 and three earlier-phase studies.", "cites": ["NCT05338450"]}, {"sentence_id": "s2", "sentence": "The Phase 3 trial (NCT05338450) was terminated due to slow recruitment and a futility analysis indicating no-go.", "cites": ["NCT05338450"]}, {"sentence_id": "s3", "sentence": "Three academic centers sponsor the running trials, all focused on remyelination outcomes using MRI or clinical measures.", "cites": ["NCT02521311"]}, {"sentence_id": "s4", "sentence": "Clemastine is approved for allergic rhinitis and urticaria, not for any neurological indication.", "cites": ["FDA:5c99e7af-86a5-4c17-82d5-2d4119e4fe72"]}, {"sentence_id": "s5", "sentence": "No drugs in the M1/H1 remyelination class have been approved for multiple sclerosis.", "cites": ["NCT05338450"]}, {"sentence_id": "s6", "sentence": "Recent preclinical studies show clemastine promotes oligodendrocyte differentiation and remyelination via M1 receptor antagonism.", "cites": ["PMID:42842169"]}, {"sentence_id": "s7", "sentence": "A 2026 animal study found that clemastine, alone or combined with selenomethionine, promoted remyelination through PI3K/Akt/mTOR signaling.", "cites": ["PMID:42622843"]}, {"sentence_id": "s8", "sentence": "The median probability of trial termination for clemastine in MS is 0.166, based on the site's risk model.", "cites": ["RISK:clemastine:MS"]}, {"sentence_id": "s9", "sentence": "Clemastine faces competition from other remyelination strategies, including combination pharmacotherapies and non-invasive brain stimulation.", "cites": ["PMID:42952812"]}], "sources": [{"id": "NCT05338450", "text": "{"nct":"NCT05338450","title":"Clemastine Fumarate as Remyelinating Treatment in Internuclear Ophthalmoparesis and Multiple Sclero…","state":"stopped","drug":"clemastine fumarate","start_year":2022,"end_year":2025,"phase":"3","overall_status":"TERMINATED","why_stopped":"In line with